// Shared toolbar editor for settings and in-capture customization.
const toolbarKeys=['toolbarMode','toolbarPosition','toolbarGroups','toolbarOrder','toolbarHidden'];
const iconPaths={select:'M4 4l6 15 2-7 7-2z',rect:'M4 4h16v16H4z',arrow:'M4 20L20 4M10 4h10v10',pen:'M4 20l4-1L20 7l-3-3L5 16z',text:'M4 5h16M12 5v15M8 20h8',highlight:'M5 16l9-12 5 4-9 12zM3 21h18',redact:'M3 6h18v12H3zM6 9h12M6 12h12M6 15h12',mosaic:'M3 3h6v6H3zM15 3h6v6h-6zM9 9h6v6H9zM3 15h6v6H3zM15 15h6v6h-6z',picker:'M5 19l2-5L17 4l3 3L10 17zM14 3l7 7',undo:'M8 4L3 9l5 5M3 9h10a7 7 0 010 14',redo:'M16 4l5 5-5 5M21 9h-10a7 7 0 000 14',pin:'M8 3h8l-1 6 4 4H5l4-4zM12 13v9',save:'M4 3h13l3 3v15H4zM8 3v6h8V3M8 21v-7h8v7',copy:'M8 8h13v13H8zM16 8V3H3v13h5',close:'M5 5l14 14M19 5L5 19',more:'M4 12h1M11 12h1M18 12h1',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6'};
function toolbarIcon(name){return `<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.more}"/></svg>`;}
function toolbarConfig(){return state.modal?.type==='toolbar-customize'?state.toolbarDraft:draft;}
function normalizeToolbar(c){const valid=toolList.map(([id])=>id);c.toolbarOrder=[...new Set([...(Array.isArray(c.toolbarOrder)?c.toolbarOrder:[]).filter(x=>valid.includes(x)),...valid])];c.toolbarHidden=(Array.isArray(c.toolbarHidden)?c.toolbarHidden:[]).filter(x=>valid.includes(x)&&x!=='select');if(!['both','icons'].includes(c.toolbarMode))c.toolbarMode='both';if(!['follow','top','bottom'].includes(c.toolbarPosition))c.toolbarPosition='follow';}
function toolbarButton(action,key,title,c,extra=''){const hint={undo:'Ctrl + Z',redo:'Ctrl + Shift + Z',copy:'Enter：默认动作',close:'Esc'}[key];return `<button data-action="${action}" ${action==='tool'?`data-value="${key}"`:''} ${extra} title="${title}${hint?' · '+hint:''}" aria-label="${title}">${toolbarIcon(key)}${c.toolbarMode==='icons'?'':`<span>${title}</span>`}</button>`;}
function toolbarContents(c,preview=false){normalizeToolbar(c);const visible=c.toolbarOrder.filter(x=>!c.toolbarHidden.includes(x)),hidden=c.toolbarOrder.filter(x=>c.toolbarHidden.includes(x));const sep=c.toolbarGroups?'<i class="divider"></i>':'';return `${visible.map(id=>toolbarButton(preview?'preview-tool':'tool',id,toolList.find(x=>x[0]===id)[1],c,`class="${!preview&&state.tool===id?'active':''}"`)).join('')}${hidden.length?toolbarButton(preview?'preview-tool':'toolbar-more','more','更多工具',c):''}${sep}${toolbarButton(preview?'preview-tool':'undo','undo','撤销',c,!preview&&!state.undoSteps.length?'disabled':'')}${toolbarButton(preview?'preview-tool':'redo','redo','重做',c,!preview&&!state.redo.length?'disabled':'')}${sep}${toolbarButton(preview?'preview-tool':'pin-capture','pin',!preview&&state.editingPin?'应用到原贴图':'贴图',c)}${toolbarButton(preview?'preview-tool':'save-capture','save','保存',c)}${toolbarButton(preview?'preview-tool':'finish-capture','copy','复制完成',c,'class="primary"')}${toolbarButton(preview?'preview-tool':'cancel-capture','close','取消截图',c)}${toolbarButton(preview?'preview-tool':'toolbar-customize','settings','自定义工具条',c)}`;}
function toolbarEditor(){const c=toolbarConfig();normalizeToolbar(c);return `<p>选择常用工具与展示方式；取消、复制和自定义入口始终保留。未常驻显示的工具仍可从“更多”使用。</p><div class="grid2"><label>展示方式 <select data-toolbar-key="toolbarMode"><option value="both" ${c.toolbarMode==='both'?'selected':''}>图标＋文字</option><option value="icons" ${c.toolbarMode==='icons'?'selected':''}>仅图标（悬停显示名称）</option></select></label><label>工具条位置 <select data-toolbar-key="toolbarPosition">${[['follow','跟随选区 / 自动避让'],['top','固定屏幕顶部'],['bottom','固定屏幕底部']].map(([v,t])=>`<option value="${v}" ${c.toolbarPosition===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="row" style="margin:16px 0"><input type="checkbox" data-toolbar-key="toolbarGroups" ${c.toolbarGroups?'checked':''}>显示工具 / 撤销重做 / 完成动作之间的分组线</label><h3>工具显示与顺序</h3><small>拖动整行排序，或使用上移 / 下移；选区工具固定显示。</small><div class="tool-order-list">${c.toolbarOrder.map((id,index)=>`<div class="tool-order-row" draggable="true" data-tool-row="${id}"><span class="drag-handle" title="拖动排序">⠿</span>${toolbarIcon(id)}<label class="grow"><input type="checkbox" data-tool-visible="${id}" ${!c.toolbarHidden.includes(id)?'checked':''} ${id==='select'?'disabled':''}> ${toolList.find(x=>x[0]===id)[1]}</label><button data-action="toolbar-up" data-value="${id}" ${index===0?'disabled':''} aria-label="上移${id}">↑</button><button data-action="toolbar-down" data-value="${id}" ${index===c.toolbarOrder.length-1?'disabled':''} aria-label="下移${id}">↓</button></div>`).join('')}</div><div class="spread" style="margin-top:20px"><h3>即时预览</h3><button data-action="toolbar-reset">恢复工具条默认</button></div><div class="toolbar-preview">${toolbarContents(c,true)}</div><small>上方预览即时变化；截图浮层右键工具条也可以自定义，应用时保留选区和已有标注。</small>`;}
function renderToolbarEditor(){if(state.modal?.type==='toolbar-customize'){const index=[...document.querySelectorAll('.modal button,.modal input,.modal select')].indexOf(document.activeElement);renderModal();document.querySelectorAll('.modal button,.modal input,.modal select')[index]?.focus();}else render();}
function openToolbarCustomize(){state.toolbarDraft=clone(saved);openModal('toolbar-customize');}
function toolbarPanel(){const palette=textColors();const colors=`<div class="row">${palette.map(c=>`<button class="swatch ${state.color.toLowerCase()===c.toLowerCase()?'active':''}" style="background:${c}" data-action="mark-color" data-value="${c}" aria-label="标注色 ${c}"></button>`).join('')}</div>`;if(state.tool==='select'&&state.objectSelected!==null)return objectPanel();if(state.tool==='select'&&state.editingPin)return '<span>单击并拖动标注，手柄调整对象大小；原图范围固定。双击使用已保存完成动作。</span>';if(state.tool==='select')return '<span>单击标注选中并拖动；空白处移动选区，边缘手柄调整大小；双击使用默认完成动作。</span>';if(state.tool==='picker')return '<div class="row"><i class="swatch active" style="background:#4b5cfa"></i><span>\u793a\u4f8b #4B5CFA \u00b7 RGB(75, 92, 250)</span><button data-action="picker-copy" data-value="hex">\u590d\u5236 HEX</button><button data-action="picker-copy" data-value="rgb">\u590d\u5236 RGB</button><small>\u539f\u56fe\u50cf\u7d20\uff08\u4e0d\u542b\u6807\u6ce8\uff09\uff1b\u5355\u51fb\u6a21\u62df\u590d\u5236 HEX</small></div>';if(state.tool==='redact'||state.tool==='mosaic')return `<div class="row"><button data-action="tool" data-value="redact" class="${state.tool==='redact'?'active':''}">实心遮盖</button><button data-action="tool" data-value="mosaic" class="${state.tool==='mosaic'?'active':''}">像素化</button><small>${state.tool==='redact'?'拖动覆盖敏感内容，导出合成图像。':'16 px 方块示意；原生版按标注顺序像素化已合成画面，不保证保密。'}</small></div>`;return `<div class="row">${colors}${state.tool==='highlight'?'':state.tool==='text'?`<label>字号 <select id="mark-text-size">${Array.from({length:37},(_,i)=>i+12).map(n=>`<option ${n===(state.textSize||saved.textSize)?'selected':''}>${n}</option>`).join('')}</select></label><span>${esc(state.textFont||saved.textFont)}</span>`:`<label>线宽 <select id="mark-stroke">${Array.from({length:12},(_,i)=>i+1).map(n=>`<option ${n===state.stroke?'selected':''}>${n}</option>`).join('')}</select></label>`}<span class="muted">${toolHint()}</span></div>`;}
function positionCaptureToolbar(){const tb=document.querySelector('.capture-toolbar'),panel=document.querySelector('.capture-properties'),desktop=document.querySelector('.desktop'),r=state.selection;if(!tb||!panel||!desktop||!r)return;const c=saved,w=desktop.clientWidth,h=desktop.clientHeight,margin=12,bottom=h-54;if(state.colorOnly){tb.style.width=Math.min(680,w-margin*2)+'px';panel.style.width=tb.style.width;tb.style.justifyContent='space-between';}const width=tb.offsetWidth,height=tb.offsetHeight,ph=panel.offsetHeight;let x=!state.colorOnly&&c.toolbarPosition==='follow'?r.x:(w-width)/2;let y;if(state.colorOnly)y=bottom-height-ph-10;else if(c.toolbarPosition==='top')y=78;else if(c.toolbarPosition==='bottom')y=bottom-height-ph-10;else{y=r.y+r.h+14;if(y+height+ph+10>bottom)y=r.y-height-ph-16;if(y<70)y=Math.max(70,bottom-height-ph-10);}x=Math.max(margin,Math.min(x,w-width-margin));y=Math.max(70,Math.min(y,bottom-height-ph-10));tb.style.left=x+'px';tb.style.top=y+'px';panel.style.left=x+'px';panel.style.top=(y+height+8)+'px';panel.style.maxWidth=Math.max(200,w-x-margin)+'px';tb.oncontextmenu=e=>{e.preventDefault();if(!state.colorOnly)openToolbarCustomize();};}
document.addEventListener('change',e=>{const el=e.target,c=toolbarConfig();if(el.dataset.toolbarKey){c[el.dataset.toolbarKey]=el.type==='checkbox'?el.checked:el.value;renderToolbarEditor();}if(el.dataset.toolVisible){const id=el.dataset.toolVisible;c.toolbarHidden=c.toolbarHidden.filter(x=>x!==id);if(!el.checked&&id!=='select')c.toolbarHidden.push(id);renderToolbarEditor();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const c=toolbarConfig(),id=b.dataset.value;switch(b.dataset.action){case 'picker-copy':pickerExample(id);break;case 'toolbar-customize':openToolbarCustomize();break;case 'toolbar-up':case 'toolbar-down':{const index=c.toolbarOrder.indexOf(id),next=index+(b.dataset.action==='toolbar-up'?-1:1);if(next>=0&&next<c.toolbarOrder.length){[c.toolbarOrder[index],c.toolbarOrder[next]]=[c.toolbarOrder[next],c.toolbarOrder[index]];renderToolbarEditor();}break;}case 'toolbar-reset':for(const k of toolbarKeys)c[k]=clone(defaults[k]);renderToolbarEditor();break;case 'toolbar-apply':for(const k of toolbarKeys){saved[k]=clone(state.toolbarDraft[k]);draft[k]=clone(state.toolbarDraft[k]);}try{localStorage.setItem('glint-prototype-v1',JSON.stringify(saved));}catch{}closeModal();render();toast('工具条已应用，选区与标注保持不变。');break;case 'toolbar-more':openModal('toolbar-more');break;case 'toolbar-more-tool':state.tool=id;closeModal();render();break;case 'preview-tool':toast('这是外观预览；保存后在截图浮层试用。');break;}});
let draggedTool=null;document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-tool-row]');if(row){draggedTool=row.dataset.toolRow;e.dataTransfer.setData('text/plain',draggedTool);e.dataTransfer.effectAllowed='move';}});document.addEventListener('dragover',e=>{if(draggedTool&&e.target.closest('[data-tool-row]'))e.preventDefault();});document.addEventListener('drop',e=>{const row=e.target.closest('[data-tool-row]');if(!row||!draggedTool)return;e.preventDefault();const c=toolbarConfig(),target=row.dataset.toolRow;if(draggedTool!==target){c.toolbarOrder.splice(c.toolbarOrder.indexOf(draggedTool),1);c.toolbarOrder.splice(c.toolbarOrder.indexOf(target),0,draggedTool);}draggedTool=null;renderToolbarEditor();});document.addEventListener('dragend',()=>draggedTool=null);

function pickerExample(format){state.drag=null;const closing=state.colorOnly;if(state.colorOnly){state.colorOnly=false;state.colorPickerFailure=false;navigate('idle',true);}(closing?completionFeedback:toast)(format==='rgb'?'RGB(75, 92, 250) \u793a\u4f8b\uff1b\u672a\u5199\u5165\u526a\u8d34\u677f\u3002':'HEX \u793a\u4f8b #4B5CFA\uff1b\u672a\u5199\u5165\u526a\u8d34\u677f\u3002');}

// Icon-only actions reveal the current translated name on keyboard focus too.
function toolbarKeyboardHint(){
 document.querySelector('.toolbar-keyboard-hint')?.remove();
 const button=document.activeElement,desktop=document.querySelector('.desktop');
 if(!desktop||state.modal||saved.toolbarMode!=='icons'||
    !button?.matches('.capture-toolbar button:focus-visible')||button.disabled)return;
 const hint=document.createElement('div');
 hint.className='toolbar-keyboard-hint';
 hint.setAttribute('aria-hidden','true');
 hint.textContent=button.getAttribute('aria-label')||button.title;
 desktop.append(hint);
 const b=button.getBoundingClientRect(),d=desktop.getBoundingClientRect();
 hint.style.left=Math.max(4,Math.min(d.width-hint.offsetWidth-4,b.left-d.left))+'px';
 const y=b.top-d.top>=32?b.top-d.top-hint.offsetHeight-4:b.bottom-d.top+4;
 hint.style.top=Math.max(4,Math.min(d.height-hint.offsetHeight-4,y))+'px';
}
document.addEventListener('focusin',toolbarKeyboardHint);
document.addEventListener('focusout',()=>document.querySelector('.toolbar-keyboard-hint')?.remove());
window.addEventListener('resize',toolbarKeyboardHint);

// Toolbar dialogs keep keyboard focus in their controls until they close.
document.addEventListener('keydown',event=>{
 if(event.key!=='Tab'||!['toolbar-customize','toolbar-more'].includes(state.modal?.type))return;
 const controls=[...document.querySelectorAll('.modal button,.modal input,.modal select')].filter(el=>!el.disabled&&el.getClientRects().length);
 if(!controls.length)return;
 event.preventDefault();
 const index=controls.indexOf(document.activeElement);
 controls[index<0?0:(index+(event.shiftKey?-1:1)+controls.length)%controls.length].focus();
},true);

document.addEventListener('change',e=>{if(e.target.id==='mark-text-size'){state.textSize=Number(e.target.value);}});

document.addEventListener('input',e=>{if(e.target.id==='annotation-font')state.textFont=e.target.value;});

document.addEventListener('input',e=>{if(e.target.id==='annotation-text')state.textDraft=e.target.value;});
